const DOM ={header: null,navLinks: null,sections: null,init(){this.header = document.querySelector('.header');this.navLinks = document.querySelectorAll('.nav-menu a');this.sections = document.querySelectorAll('section[id]');}};const HEADER_SCROLL_OFFSET = 80;const CONTENT_VISIBILITY_SECTIONS = '.library,.about,.faq';function getHeaderScrollOffset(){return DOM.header?.offsetHeight || HEADER_SCROLL_OFFSET;}function revealAnchorTarget(target){const lazySection = target.closest(CONTENT_VISIBILITY_SECTIONS);if(lazySection){lazySection.style.contentVisibility = 'visible';}}function getAnchorScrollTop(target){revealAnchorTarget(target);return Math.max(0,target.getBoundingClientRect().top + window.pageYOffset - getHeaderScrollOffset());}function scrollToAnchorTarget(target,behavior = 'smooth',updateHash = true){if(!target)return;const targetId = target.id;const scroll =(scrollBehavior)=>{window.scrollTo({top: getAnchorScrollTop(target),behavior: scrollBehavior});};scroll(behavior);if(updateHash && targetId){history.pushState(null,'',`#${targetId}`);}[350,900,1600].forEach(delay =>{setTimeout(()=> scroll('auto'),delay);});}function getTargetFromHash(hash){if(!hash || hash.length <= 1)return null;try{return document.getElementById(decodeURIComponent(hash.slice(1)));}catch(error){return null;}}document.querySelectorAll('a[href^="#"]').forEach(anchor =>{anchor.addEventListener('click',function(e){const href = this.getAttribute('href');const targetId = href ? decodeURIComponent(href.slice(1)): '';const target = targetId ? document.getElementById(targetId): null;if(!target)return;e.preventDefault();scrollToAnchorTarget(target);});});window.addEventListener('hashchange',()=>{const target = getTargetFromHash(window.location.hash);if(target){requestAnimationFrame(()=> scrollToAnchorTarget(target,'auto',false));}});let scrollTicking = false;const handleScroll =()=>{const currentScrollY = window.scrollY;if(DOM.header){if(currentScrollY > 50){DOM.header.classList.add('scrolled');}else{DOM.header.classList.remove('scrolled');}}updateActiveNav(currentScrollY);scrollTicking = false;};window.addEventListener('scroll',()=>{if(!scrollTicking){requestAnimationFrame(handleScroll);scrollTicking = true;}},{passive: true});const navObserverOptions ={threshold: 0.5,rootMargin: '-80px 0px -50% 0px'};const navObserver = new IntersectionObserver((entries)=>{if(!DOM.navLinks)DOM.navLinks = document.querySelectorAll('.nav-menu a');entries.forEach(entry =>{if(entry.isIntersecting){DOM.navLinks.forEach(link =>{link.classList.remove('active');if(link.getAttribute('href').slice(1)=== entry.target.id){link.classList.add('active');}});}});},navObserverOptions);DOM.sections = document.querySelectorAll('section[id]');DOM.sections.forEach(section => navObserver.observe(section));let sectionDataCache = [];let sectionCacheValid = false;function rebuildSectionCache(){if(!DOM.sections)DOM.sections = document.querySelectorAll('section[id]');sectionDataCache = Array.from(DOM.sections).map(section =>({id: section.id,top: section.offsetTop,height: section.offsetHeight}));sectionCacheValid = true;}function updateActiveNav(scrollY){if(!sectionCacheValid){rebuildSectionCache();}if(!DOM.navLinks)DOM.navLinks = document.querySelectorAll('.nav-menu a');let currentSectionId = null;const scrollPosition =(typeof scrollY === 'number' ? scrollY : window.scrollY)+ 100;for(const section of sectionDataCache){if(scrollPosition >= section.top && scrollPosition < section.top + section.height){currentSectionId = section.id;break;}}DOM.navLinks.forEach(link =>{const href = link.getAttribute('href').slice(1);if(currentSectionId && href === currentSectionId){link.classList.add('active');}else{link.classList.remove('active');}});}const observerOptions ={threshold: 0.1,rootMargin: '0px 0px -100px 0px'};const observer = new IntersectionObserver((entries)=>{requestAnimationFrame(()=>{entries.forEach(entry =>{if(entry.isIntersecting){entry.target.classList.add('active');observer.unobserve(entry.target);}});});},observerOptions);document.addEventListener('DOMContentLoaded',()=>{DOM.init();const hashTarget = getTargetFromHash(window.location.hash);if(hashTarget){requestAnimationFrame(()=> scrollToAnchorTarget(hashTarget,'auto',false));}requestAnimationFrame(()=>{rebuildSectionCache();});requestAnimationFrame(()=>{const revealElements = document.querySelectorAll('.hero-content');revealElements.forEach(el =>{el.classList.add('reveal');observer.observe(el);});setTimeout(()=>{const otherElements = document.querySelectorAll('.book-card,.section-title,.about-content');otherElements.forEach(el =>{el.classList.add('reveal');observer.observe(el);});},500);});createMobileMenu();const idleInit =()=>{initParallax();initAudio();initParticles();initFAQ();};if('requestIdleCallback' in window){requestIdleCallback(idleInit,{timeout: 3000});}else{setTimeout(idleInit,1000);}updateActiveNav();let rebuildTimeout;const resizeObserver = new ResizeObserver(()=>{clearTimeout(rebuildTimeout);rebuildTimeout = setTimeout(()=>{requestAnimationFrame(rebuildSectionCache);},200);});if(DOM.sections){DOM.sections.forEach(section =>{resizeObserver.observe(section);});}});const initAudio =()=>{const audioBtn = document.getElementById('audio-toggle');const audio = document.getElementById('temple-audio');if(!audioBtn || !audio)return;const updateAudioButton =(isPlaying)=>{audioBtn.classList.toggle('playing',isPlaying);audioBtn.setAttribute('data-state',isPlaying ? 'playing' : 'paused');audioBtn.setAttribute('aria-label',isPlaying ? 'Stop Temple Ambience' : 'Play Temple Ambience');};const source = audio.currentSrc || audio.getAttribute('src')|| audio.querySelector('source')?.getAttribute('src');if(!source){audioBtn.disabled = true;audioBtn.setAttribute('aria-label','Temple Ambience Unavailable');return;}audio.volume = 0.4;audio.load();updateAudioButton(false);audioBtn.addEventListener('click',async()=>{if(!audio.paused){audio.pause();}else{try{await audio.play();}catch(err){console.log('Audio play failed:',err);updateAudioButton(false);}}});audio.addEventListener('play',()=> updateAudioButton(true));audio.addEventListener('pause',()=> updateAudioButton(false));audio.addEventListener('ended',()=> updateAudioButton(false));};const initParallax =()=>{console.log('Parallax effect disabled(was causing CLS)');};const createMobileMenu =()=>{const toggle = document.querySelector('.nav-toggle');const menu = document.querySelector('.nav-menu');if(!toggle || !menu)return;toggle.addEventListener('click',()=>{const isOpen = menu.classList.toggle('open');toggle.setAttribute('aria-expanded',String(isOpen));});menu.querySelectorAll('a').forEach(link =>{link.addEventListener('click',()=>{menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');});});document.addEventListener('click',(e)=>{if(!toggle.closest('header').contains(e.target)){menu.classList.remove('open');toggle.setAttribute('aria-expanded','false');}});};document.querySelectorAll('.btn').forEach(button =>{button.addEventListener('click',(e)=>{const bookTitle = e.target.closest('.book-card')?.querySelector('.book-title')?.textContent;const linkType = e.target.classList.contains('btn-primary')? 'PDF Download' : 'External Link';console.log(`User clicked: ${linkType}for ${bookTitle}`);});});document.querySelectorAll('a[target="_blank"]').forEach(link =>{link.addEventListener('click',function(){this.style.opacity = '0.6';setTimeout(()=>{this.style.opacity = '1';},300);});});const initParticles =()=>{const container = document.querySelector('.particles-container');if(!container)return;const particleCount = 15;for(let i = 0;i < particleCount;i++){const particle = document.createElement('div');particle.className = 'particle';particle.style.left = Math.random()* 100 + '%';particle.style.top = Math.random()* 100 + '%';particle.style.animationDelay =(i * 0.5)+ 's';particle.style.animationDuration =(6 + Math.random()* 4)+ 's';container.appendChild(particle);}};const initFAQ =()=>{const faqBlocks = document.querySelectorAll('.faq-block');faqBlocks.forEach(block =>{const summary = block.querySelector('summary');const content = block.querySelector('.faq-content');if(!summary || !content)return;if(!content.querySelector('.faq-content-inner')){const inner = document.createElement('div');inner.className = 'faq-content-inner';while(content.firstChild){inner.appendChild(content.firstChild);}content.appendChild(inner);}summary.addEventListener('click',(e)=>{e.preventDefault();const isOpen = block.hasAttribute('open');if(isOpen){const contentHeight = content.scrollHeight;requestAnimationFrame(()=>{content.style.maxHeight = contentHeight + 'px';requestAnimationFrame(()=>{content.style.maxHeight = '0';});});setTimeout(()=>{block.removeAttribute('open');content.style.maxHeight = '';},400);}else{const openBlocks = Array.from(document.querySelectorAll('.faq-block[open]')).filter(b => b !== block);const openData = openBlocks.map(openBlock =>{const openContent = openBlock.querySelector('.faq-content');return{block: openBlock,content: openContent,height: openContent.scrollHeight};});openData.forEach(data =>{requestAnimationFrame(()=>{data.content.style.maxHeight = data.height + 'px';requestAnimationFrame(()=>{data.content.style.maxHeight = '0';});});setTimeout(()=>{data.block.removeAttribute('open');data.content.style.maxHeight = '';},400);});block.setAttribute('open','');requestAnimationFrame(()=>{const contentHeight = content.scrollHeight;content.style.maxHeight = '0';requestAnimationFrame(()=>{content.style.maxHeight = contentHeight + 'px';});});setTimeout(()=>{content.style.maxHeight = 'none';},400);}});});};